using System.Globalization;
using System.Text;
using System.Text.Json;
using Microsoft.EntityFrameworkCore;
using static Clubs.Access;
namespace Clubs;

public static class LeadershipCenter
{
    public record VacancyNote(string Reason,string Priority,DateOnly? ExpectedFillingDate,string ResponsibleAuthority,string? PreviousValue=null);
    sealed record Scope(Assignment Workspace,string[] Grants,Guid[] Ids,List<Org> Units);
    static async Task<Scope> Scoped(Access a,Guid? orgId){var w=await a.Workspace("leadership.view");var grants=await a.Grants(w);var q=a.Visible(w).AsNoTracking();if(orgId!=null){Check(await q.AnyAsync(o=>o.Id==orgId),"Organizational scope not found.",404);var branch=a.Tree(w.TenantId,orgId.Value).Select(o=>o.Id);q=q.Where(o=>branch.Contains(o.Id));}var units=await q.OrderBy(o=>o.Name).ToListAsync();Check(units.Count<=15000,"Choose a narrower organizational scope.");return new(w,grants.ToArray(),units.Select(o=>o.Id).ToArray(),units);}
    static IQueryable<OfficerAppointment> Appointments(Db db,Scope s)=>db.OfficerAppointments.AsNoTracking().Where(p=>p.TenantId==s.Workspace.TenantId&&s.Ids.Contains(p.OrgId));
    static IQueryable<Person> People(Db db,Scope s)=>db.Persons.Where(p=>db.OfficerAppointments.Any(a=>a.PersonId==p.Id&&a.TenantId==s.Workspace.TenantId&&s.Ids.Contains(a.OrgId))||(s.Grants.Contains("members.view")&&db.Memberships.Any(m=>m.PersonId==p.Id&&m.TenantId==s.Workspace.TenantId&&s.Ids.Contains(m.ClubId))));
    static DateTimeOffset Date(string? value,DateTimeOffset fallback){if(string.IsNullOrEmpty(value))return fallback;Check(DateOnly.TryParseExact(value,"yyyy-MM-dd",CultureInfo.InvariantCulture,DateTimeStyles.None,out _),"Use YYYY-MM-DD dates.");return new DateTimeOffset(DateOnly.ParseExact(value,"yyyy-MM-dd").ToDateTime(TimeOnly.MinValue),TimeSpan.Zero);}
    static IQueryable<OfficerAppointment> Filter(IQueryable<OfficerAppointment> q,Db db,string? status,Guid? positionId,string? search){if(positionId!=null)q=q.Where(p=>p.PositionId==positionId);if(status=="Current")q=q.Where(p=>GovernanceService.Current(db).Any(c=>c.Id==p.Id));else if(status=="Expiring")q=q.Where(p=>GovernanceService.Current(db).Any(c=>c.Id==p.Id)&&p.EndsAt<DateTimeOffset.UtcNow.AddDays(90));else if(status=="Upcoming")q=q.Where(p=>p.StartsAt>DateTimeOffset.UtcNow&&new[]{"Proposed","Pending approval","Approved","Scheduled"}.Contains(p.Status));else if(!string.IsNullOrEmpty(status)){Check(new[]{"Active","Proposed","Pending approval","Approved","Scheduled","Completed","Cancelled","Revoked"}.Contains(status),"Unsupported appointment status.");q=q.Where(p=>p.Status==status);}if(!string.IsNullOrWhiteSpace(search)){Check(search.Length<=120,"Search is too long.");q=q.Where(p=>db.Persons.Any(x=>x.Id==p.PersonId&&EF.Functions.ILike(x.DisplayName,"%"+search+"%"))||db.OfficerPositions.Any(x=>x.Id==p.PositionId&&EF.Functions.ILike(x.Title,"%"+search+"%"))||db.Orgs.Any(x=>x.Id==p.OrgId&&EF.Functions.ILike(x.Name,"%"+search+"%")));}return q;}
    static IQueryable<object> Rows(IQueryable<OfficerAppointment> q,Db db,Scope s)=>q.Select(p=>(object)new{p.Id,p.PersonId,p.OrgId,p.PositionId,p.StartsAt,p.EndsAt,p.EffectiveAt,p.Status,p.Method,p.TermId,p.Version,p.Notes,name=db.Persons.Where(x=>x.Id==p.PersonId).Select(x=>x.DisplayName).First(),title=db.OfficerPositions.Where(x=>x.Id==p.PositionId).Select(x=>x.Title).First(),organization=db.Orgs.Where(x=>x.Id==p.OrgId).Select(x=>x.Name).First(),level=db.Orgs.Where(x=>x.Id==p.OrgId).Select(x=>db.Levels.Where(l=>l.Id==x.LevelId).Select(l=>l.ParentLevelId==null?"International":l.Name).First()).First(),current=GovernanceService.Current(db).Any(x=>x.Id==p.Id),hasPhoto=db.Persons.Any(x=>x.Id==p.PersonId&&x.Photo!=null&&(x.Privacy.PhotoVisible||s.Grants.Contains("members.personal.view")||x.UserId==s.Workspace.UserId))});
    public static void MapLeadershipCenter(this RouteGroupBuilder api)
    {
        api.MapGet("/leadership/center",Summary);
        api.MapGet("/leadership/people",Directory);
        api.MapGet("/leadership/people/{id:guid}",async(Guid id,MembershipService members)=>{
            var s=await Scoped(members.Access,null);var db=members.Db;Check(await People(db,s).AnyAsync(p=>p.Id==id),"Person outside authorized scope.",404);
            var p=await members.People.SingleAsync(p=>p.Id==id);var own=p.UserId==s.Workspace.UserId;var personal=s.Grants.Contains("members.personal.view");
            var profile=await members.Profile(p,personal||own,s.Grants.Contains("members.contacts.view")||own,s.Grants.Contains("members.view")||own,own,!s.Grants.Contains("members.view"));
            var appointments=await Rows(Appointments(db,s).Where(a=>a.PersonId==id).OrderByDescending(a=>a.StartsAt),db,s).Take(200).ToListAsync();
            var mids=db.Memberships.Where(m=>m.PersonId==id&&m.TenantId==s.Workspace.TenantId&&s.Ids.Contains(m.ClubId));
            var affiliations=await mids.Select(m=>new{m.Id,m.Number,m.ClubId,m.Status,m.JoinedAt,club=m.Club.Name}).ToListAsync();
            object? committees=null;if(s.Grants.Contains("committees.view"))committees=await db.CommitteeMemberships.Where(m=>m.TenantId==s.Workspace.TenantId&&m.PersonId==id&&db.Committees.Any(c=>c.Id==m.CommitteeId&&s.Ids.Contains(c.OrgId))).Select(m=>new{m.Id,m.CommitteeId,m.Responsibilities,m.Status,m.StartsAt,m.EndsAt,name=db.Committees.Where(c=>c.Id==m.CommitteeId).Select(c=>c.Name).First(),role=db.CommitteeRoles.Where(r=>r.Id==m.RoleId).Select(r=>r.Name).First()}).Take(100).ToListAsync();
            var apids=Appointments(db,s).Where(a=>a.PersonId==id).Select(a=>a.Id);var history=await db.OfficerAppointmentHistory.Where(h=>h.TenantId==s.Workspace.TenantId&&apids.Contains(h.AppointmentId)).OrderByDescending(h=>h.At).Select(h=>new{h.Id,h.AppointmentId,h.At,h.Status,h.Detail}).Take(100).ToListAsync();
            return Results.Ok(new{profile,appointments,affiliations,committees,history,capabilities=new{contacts=s.Grants.Contains("members.contacts.view"),personal,manage=s.Grants.Contains("leadership.manage")}});
        });
        api.MapGet("/leadership/people/{id:guid}/photo",async(Guid id,Access a)=>{var s=await Scoped(a,null);var p=await People(a.Db,s).Where(p=>p.Id==id).Select(p=>new{p.Photo,p.PhotoType,p.UserId,p.Privacy.PhotoVisible}).SingleOrDefaultAsync();Check(p!=null&&p.Photo!=null&&(p.PhotoVisible||s.Grants.Contains("members.personal.view")||p.UserId==s.Workspace.UserId),"Photo unavailable.",404);return Results.File(p!.Photo!,p.PhotoType==""?"image/jpeg":p.PhotoType);});
        api.MapPut("/leadership/vacancies/{orgId:guid}/{positionId:guid}",async(Guid orgId,Guid positionId,VacancyNote input,Access a)=>{
            var s=await Scoped(a,orgId);Check(s.Grants.Contains("leadership.manage"),"Leadership management required.",403);Check(input.Reason!=null&&input.ResponsibleAuthority!=null&&input.Reason.Length<=2000&&input.ResponsibleAuthority.Length<=200&&new[]{"Low","Medium","High","Urgent"}.Contains(input.Priority),"Invalid vacancy details.");Check(await a.Db.OfficerPositions.AnyAsync(p=>p.Id==positionId&&p.TenantId==s.Workspace.TenantId&&p.LevelId==s.Units.First(o=>o.Id==orgId).LevelId),"Position is not applicable.",400);
            await using var tx=await a.Mutation(s.Workspace);var key="leadership.vacancy."+positionId;var row=await a.Db.OrganizationSettings.SingleOrDefaultAsync(x=>x.TenantId==s.Workspace.TenantId&&x.OrgId==orgId&&x.Key==key);Check((row?.Value??"")== (input.PreviousValue??""),"Vacancy note changed. Refresh before editing.",409);if(row==null){row=new(){TenantId=s.Workspace.TenantId,OrgId=orgId,Key=key};a.Db.OrganizationSettings.Add(row);}row.Value=JsonSerializer.Serialize(new{input.Reason,input.Priority,input.ExpectedFillingDate,input.ResponsibleAuthority,updatedAt=DateTimeOffset.UtcNow});await a.Log(s.Workspace,"leadership.vacancy.updated",orgId+"/"+positionId,row.Value);await a.Db.SaveChangesAsync();await tx.CommitAsync();return Results.Ok(new{row.Value});
        });
        api.MapPost("/leadership/reminders",async(Guid? orgId,Access a,NotificationService notifications)=>{
            var s=await Scoped(a,orgId);Check(s.Grants.Contains("leadership.manage"),"Leadership management required.",403);await using var tx=await a.Mutation(s.Workspace);var now=DateTimeOffset.UtcNow;var due=await Appointments(a.Db,s).Where(p=>GovernanceService.Current(a.Db).Any(c=>c.Id==p.Id)&&p.EndsAt<now.AddDays(90)).OrderBy(p=>p.EndsAt).Take(100).ToListAsync();var queued=0;
            foreach(var p in due){var user=await a.Db.Persons.Where(x=>x.Id==p.PersonId).Select(x=>x.UserId).SingleAsync();if(user==null)continue;var link="/app/leadership/appointments?appointment="+p.Id;var exists=await a.Db.Mails.AnyAsync(m=>m.TenantId==s.Workspace.TenantId&&m.UserId==user&&m.Kind=="leadership.term-expiry"&&m.Link==link&&m.CreatedAt>=now.Date);if(exists)continue;await notifications.User(user,"leadership.term-expiry","Your leadership term ends on "+p.EndsAt.ToString("yyyy-MM-dd")+". Review your appointment and handover.",link,s.Workspace.TenantId,p.OrgId);queued++;}
            await a.Log(s.Workspace,"leadership.reminders.queued",orgId?.ToString()??s.Workspace.OrgId.ToString(),queued.ToString());await a.Db.SaveChangesAsync();await tx.CommitAsync();return Results.Ok(new{queued,channel="Existing notification outbox; transactional preferences apply. WhatsApp is not configured."});
        });
        api.MapGet("/leadership/vacancies/{orgId:guid}/{positionId:guid}/history",async(Guid orgId,Guid positionId,Access a)=>{var s=await Scoped(a,orgId);var resource=orgId+"/"+positionId;return Results.Ok(await a.Db.Audits.Where(x=>x.TenantId==s.Workspace.TenantId&&x.Action=="leadership.vacancy.updated"&&x.Resource==resource).OrderByDescending(x=>x.At).Select(x=>new{x.Id,x.At,x.Changes}).Take(50).ToListAsync());});
        api.MapGet("/leadership/people/export",async(Access a,Guid? orgId,string? search,Guid? positionId,string? membershipStatus,string sort="name",int page=1)=>{
            var scope=await Scoped(a,orgId);Check(scope.Grants.Contains("members.export")||scope.Grants.Contains("governance.reports"),"Export permission required.",403);
            var result=await Directory(a,orgId,search,positionId,membershipStatus,sort,page);var value=((IValueHttpResult)result).Value;var json=JsonSerializer.SerializeToElement(value,new JsonSerializerOptions{PropertyNamingPolicy=JsonNamingPolicy.CamelCase});
            string Csv(string value)=>"\""+MembershipImport.Safe(value).Replace("\"","\"\"")+"\"";var rows=new List<string>{"Person ID,Name,Email,Phone,Active appointments,Membership IDs,Clubs"};
            foreach(var item in json.GetProperty("items").EnumerateArray()){var fields=new[]{item.GetProperty("id").ToString(),item.GetProperty("name").ToString(),item.GetProperty("email").ToString(),item.GetProperty("phone").ToString(),item.GetProperty("activeAppointments").ToString(),string.Join("; ",item.GetProperty("memberships").EnumerateArray().Select(m=>m.GetProperty("number").ToString())),string.Join("; ",item.GetProperty("memberships").EnumerateArray().Select(m=>m.GetProperty("club").ToString()))};rows.Add(string.Join(',',fields.Select(Csv)));}await a.Log(scope.Workspace,"leadership.people.export","page "+page);return Results.File(Encoding.UTF8.GetBytes("\uFEFF"+string.Join("\r\n",rows)),"text/csv","impact-leadership-people-page.csv");
        });
        api.MapGet("/leadership/export",async(HttpRequest request,Access a,Guid? orgId,string? status,Guid? positionId,string? search)=>{
            var s=await Scoped(a,orgId);Check(s.Grants.Contains("members.export")||s.Grants.Contains("governance.reports"),"Export permission required.",403);var q=Filter(Appointments(a.Db,s),a.Db,status,positionId,search);Check(await q.CountAsync()<=10000,"Narrow exports to 10,000 appointments.");var data=await Rows(q.OrderBy(p=>p.StartsAt),a.Db,s).ToListAsync();var lines=new List<string>{"Name,Office,Organization,Status,Starts,Ends,Person ID"};string Cell(string x)=>"\""+MembershipImport.Safe(x).Replace("\"","\"\"")+"\"";
            foreach(var row in data){var e=JsonSerializer.SerializeToElement(row,new JsonSerializerOptions{PropertyNamingPolicy=JsonNamingPolicy.CamelCase});lines.Add(string.Join(',',new[]{"name","title","organization","status","startsAt","endsAt","personId"}.Select(k=>Cell(e.GetProperty(k).ToString()))));}await a.Log(s.Workspace,"leadership.export","appointments");return Results.File(Encoding.UTF8.GetBytes("\uFEFF"+string.Join("\r\n",lines)),"text/csv","impact-leadership.csv");
        });
    }
    static async Task<IResult> Summary(HttpRequest request,Access a,Guid? orgId=null,Guid? positionId=null,string? status=null,string? search=null,int page=1,string? from=null,string? to=null,string? mode=null)
    {
        var watch=System.Diagnostics.Stopwatch.StartNew();var s=await Scoped(a,orgId);var db=a.Db;var now=DateTimeOffset.UtcNow;var start=Date(from,new DateTimeOffset(now.Year,1,1,0,0,0,TimeSpan.Zero));var end=Date(to,new DateTimeOffset(now.Date,TimeSpan.Zero)).AddDays(1);Check(start<end&&end<=now.Date.AddDays(2)&&start.Year>=1900&&(end-start).TotalDays<=3660,"Choose a valid period of up to ten years.");var prior=start-(end-start);
        var baseQuery=Appointments(db,s);if(positionId!=null){Check(await db.OfficerPositions.AnyAsync(p=>p.Id==positionId&&p.TenantId==s.Workspace.TenantId),"Office position not found.",404);baseQuery=baseQuery.Where(p=>p.PositionId==positionId);}
        var positions=await db.OfficerPositions.AsNoTracking().Where(p=>p.TenantId==s.Workspace.TenantId).ToListAsync();var levels=await db.Levels.Where(l=>l.TenantId==s.Workspace.TenantId).ToDictionaryAsync(l=>l.Id,l=>l.ParentLevelId==null?"International":l.Name);
        var all=await baseQuery.Select(p=>new{p.Id,p.OrgId,p.PersonId,p.PositionId,p.Status,p.StartsAt,p.EndsAt,p.EffectiveAt,p.CreatedAt,current=GovernanceService.Current(db).Any(c=>c.Id==p.Id)}).ToListAsync();Check(all.Count<=100000,"Narrow leadership scope.");var current=all.Where(p=>p.current).ToList();var settings=await db.OrganizationSettings.Where(x=>x.TenantId==s.Workspace.TenantId&&s.Ids.Contains(x.OrgId)&&x.Key.StartsWith("leadership.vacancy.")).ToListAsync();
        var vacant=new List<object>();foreach(var org in s.Units.Where(o=>o.Status=="Active"))foreach(var position in positions.Where(p=>p.Active&&p.Mandatory&&p.LevelId==org.LevelId&&(positionId==null||p.Id==positionId))){if(current.Any(p=>p.OrgId==org.Id&&p.PositionId==position.Id))continue;var last=all.Where(p=>p.OrgId==org.Id&&p.PositionId==position.Id&&p.EndsAt<=now&&new[]{"Completed","Revoked","Active"}.Contains(p.Status)).OrderByDescending(p=>p.EndsAt).FirstOrDefault();var note=settings.FirstOrDefault(x=>x.OrgId==org.Id&&x.Key=="leadership.vacancy."+position.Id);vacant.Add(new{orgId=org.Id,organization=org.Name,positionId=position.Id,title=position.Title,level=levels[org.LevelId],since=last?.EndsAt,ageDays=last==null?(int?)null:(int)(now-last.EndsAt).TotalDays,note=note?.Value??"",upcoming=all.Count(p=>p.OrgId==org.Id&&p.PositionId==position.Id&&p.StartsAt>now&&new[]{"Proposed","Pending approval","Approved","Scheduled"}.Contains(p.Status))});}
        var vacancyRows=vacant.Where(v=>string.IsNullOrWhiteSpace(search)||v.ToString()!.Contains(search,StringComparison.OrdinalIgnoreCase)).ToList();
        var required=s.Units.Where(o=>o.Status=="Active").Sum(o=>positions.Count(p=>p.Active&&p.Mandatory&&p.LevelId==o.LevelId&&(positionId==null||p.Id==positionId)));var filtered=Filter(baseQuery,db,status,positionId,search);page=Math.Clamp(page,1,10000);var total=await filtered.CountAsync();
        var recent=await db.OfficerAppointmentHistory.Where(h=>h.TenantId==s.Workspace.TenantId&&baseQuery.Any(p=>p.Id==h.AppointmentId)).OrderByDescending(h=>h.At).Select(h=>new{h.Id,h.AppointmentId,h.Status,h.Detail,h.At}).Take(15).ToListAsync();
        var due=current.Where(p=>p.EndsAt<now.AddDays(90)).OrderBy(p=>p.EndsAt).ToList();var succession=due.Take(100).Select(p=>new{p.Id,p.OrgId,p.PersonId,p.PositionId,p.EndsAt,candidates=all.Where(n=>n.OrgId==p.OrgId&&n.PositionId==p.PositionId&&n.StartsAt>=p.EndsAt&&new[]{"Proposed","Pending approval","Approved","Scheduled"}.Contains(n.Status)).OrderBy(n=>n.StartsAt).Select(n=>new{n.Id,n.PersonId,n.StartsAt,n.EndsAt,n.Status}).ToList()}).ToList();
        object? committees=null;if(s.Grants.Contains("committees.view"))committees=await db.Committees.Where(c=>c.TenantId==s.Workspace.TenantId&&s.Ids.Contains(c.OrgId)).GroupBy(c=>c.Status).Select(g=>new{status=g.Key,count=g.Count()}).ToListAsync();
        var totals=new{officeBearers=all.Select(p=>p.PersonId).Distinct().Count(),activeLeaders=current.Select(p=>p.PersonId).Distinct().Count(),activeAppointments=current.Count,vacancies=vacant.Count,required,coverage=required==0?(double?)null:Math.Round(100d*(required-vacant.Count)/required,1),expiring30=due.Count(p=>p.EndsAt<now.AddDays(30)),expiring60=due.Count(p=>p.EndsAt<now.AddDays(60)),expiring90=due.Count,pending=all.Count(p=>new[]{"Proposed","Pending approval"}.Contains(p.Status)),scheduled=all.Count(p=>new[]{"Approved","Scheduled"}.Contains(p.Status)&&p.StartsAt>now),appointmentsInPeriod=all.Count(p=>p.CreatedAt>=start&&p.CreatedAt<end),previousAppointments=all.Count(p=>p.CreatedAt>=prior&&p.CreatedAt<start),withoutSuccessor=succession.Count(p=>p.candidates.Count==0)};
        var trend=all.SelectMany(p=>new[]{new{at=p.StartsAt,kind="Appointments"},new{at=p.EndsAt,kind="Term ends"}}).Where(x=>x.at>=start&&x.at<end).GroupBy(x=>new{month=x.at.ToString("yyyy-MM"),x.kind}).Select(g=>new{g.Key.month,g.Key.kind,count=g.Count()}).OrderBy(x=>x.month).ToList();
        var distribution=s.Units.GroupBy(o=>levels[o.LevelId]).Select(g=>new{level=g.Key,units=g.Count(),appointments=current.Count(p=>g.Any(o=>o.Id==p.OrgId)),people=current.Where(p=>g.Any(o=>o.Id==p.OrgId)).Select(p=>p.PersonId).Distinct().Count(),required=g.Where(o=>o.Status=="Active").Sum(o=>positions.Count(p=>p.Active&&p.Mandatory&&p.LevelId==o.LevelId&&(positionId==null||p.Id==positionId))),filled=g.Where(o=>o.Status=="Active").Sum(o=>positions.Count(p=>p.Active&&p.Mandatory&&p.LevelId==o.LevelId&&(positionId==null||p.Id==positionId)&&current.Any(c=>c.OrgId==o.Id&&c.PositionId==p.Id)))}).ToList();
        var root=s.Units.FirstOrDefault(o=>o.Id==orgId)??s.Units.FirstOrDefault(o=>o.ParentId==null||!s.Ids.Contains(o.ParentId.Value));var teams=root==null?[]:await Rows(baseQuery.Where(p=>p.OrgId==root.Id&&GovernanceService.Current(db).Any(c=>c.Id==p.Id)).OrderBy(p=>p.StartsAt),db,s).Take(40).ToListAsync();
        var teamOrgIds=root==null?Array.Empty<Guid>():s.Units.Where(o=>o.Id==root.Id||o.ParentId==root.Id).Take(40).Select(o=>o.Id).ToArray();var branchTeam=await Rows(baseQuery.Where(p=>teamOrgIds.Contains(p.OrgId)&&GovernanceService.Current(db).Any(c=>c.Id==p.Id)).OrderBy(p=>p.OrgId),db,s).Take(120).ToListAsync();
        var upcoming=await Rows(baseQuery.Where(p=>GovernanceService.Current(db).Any(c=>c.Id==p.Id)&&p.EndsAt<now.AddDays(90)).OrderBy(p=>p.EndsAt),db,s).Take(100).ToListAsync();
        return Results.Ok(new{summary=totals,total,page,size=20,items=await Rows(filtered.OrderByDescending(p=>p.StartsAt).ThenBy(p=>p.Id).Skip((page-1)*20).Take(20),db,s).ToListAsync(),vacancies=new{total=vacancyRows.Count,items=vacancyRows.Skip((page-1)*20).Take(20)},succession,upcoming,teams,branchTeam,trend,distribution,recent,committees,positions,rootId=root?.Id,units=s.Units.Select(o=>new{o.Id,o.ParentId,o.LevelId,o.Name,o.Code,o.Country,o.State,o.Status,level=levels[o.LevelId],children=s.Units.Count(c=>c.ParentId==o.Id),current=current.Count(p=>p.OrgId==o.Id)}),capabilities=new{manage=s.Grants.Contains("leadership.manage"),contacts=s.Grants.Contains("members.contacts.view"),members=s.Grants.Contains("members.view"),committees=s.Grants.Contains("committees.view"),export=s.Grants.Contains("members.export")||s.Grants.Contains("governance.reports"),configure=s.Grants.Contains("governance.configure")},meta=new{from=start,to=end,asOf=now,elapsedMs=watch.ElapsedMilliseconds,definition="Current coverage uses configured active mandatory offices and effective appointments, including organization and membership eligibility. Counts are scoped. Appointment comparisons count creation dates; charts show recorded term starts and ends, not completed transitions. Vacancy age is unknown without a recorded prior term end. Approved future appointments and unapproved proposals remain distinct."}});
    }
    static async Task<IResult> Directory(Access a,Guid? orgId=null,string? search=null,Guid? positionId=null,string? membershipStatus=null,string sort="name",int page=1)
    {
        var s=await Scoped(a,orgId);var db=a.Db;var q=People(db,s);var contacts=s.Grants.Contains("members.contacts.view");var staff=s.Grants.Contains("members.view");var user=s.Workspace.UserId;
        if(positionId!=null)q=q.Where(p=>Appointments(db,s).Any(x=>x.PersonId==p.Id&&x.PositionId==positionId));
        if(!string.IsNullOrEmpty(membershipStatus))q=q.Where(p=>db.Memberships.Any(m=>m.PersonId==p.Id&&m.TenantId==s.Workspace.TenantId&&s.Ids.Contains(m.ClubId)&&m.Status==membershipStatus));
        if(!string.IsNullOrWhiteSpace(search)){Check(search.Length<=120,"Search too long.");q=q.Where(p=>EF.Functions.ILike(p.DisplayName,"%"+search+"%")||db.Memberships.Any(m=>m.PersonId==p.Id&&m.TenantId==s.Workspace.TenantId&&s.Ids.Contains(m.ClubId)&&(EF.Functions.ILike(m.Number,"%"+search+"%")||EF.Functions.ILike(m.Club.Name,"%"+search+"%")))||db.OfficerAppointments.Any(x=>x.PersonId==p.Id&&x.TenantId==s.Workspace.TenantId&&s.Ids.Contains(x.OrgId)&&db.OfficerPositions.Any(o=>o.Id==x.PositionId&&EF.Functions.ILike(o.Title,"%"+search+"%")))||(contacts&&p.Contacts.Any(c=>((c.Kind=="Email"&&(staff||p.Privacy.DisplayEmail||p.UserId==user))||(c.Kind=="Phone"&&(staff||p.Privacy.DisplayPhone||p.UserId==user)))&&EF.Functions.ILike(c.Value,"%"+search+"%"))));}
        Check(new[]{"name","name-desc","newest"}.Contains(sort),"Invalid sort.");var total=await q.CountAsync();page=Math.Clamp(page,1,10000);var ordered=sort=="name-desc"?q.OrderByDescending(p=>p.DisplayName):sort=="newest"?q.OrderByDescending(p=>p.CreatedAt):q.OrderBy(p=>p.DisplayName);
        var items=await ordered.ThenBy(p=>p.Id).Skip((page-1)*20).Take(20).Select(p=>new{p.Id,name=p.DisplayName,hasPhoto=p.Photo!=null&&(p.Privacy.PhotoVisible||s.Grants.Contains("members.personal.view")||p.UserId==user),email=contacts&&(staff||p.Privacy.DisplayEmail||p.UserId==user)?p.Contacts.Where(c=>c.Kind=="Email").Select(c=>c.Value).FirstOrDefault():null,phone=contacts&&(staff||p.Privacy.DisplayPhone||p.UserId==user)?p.Contacts.Where(c=>c.Kind=="Phone").Select(c=>c.Value).FirstOrDefault():null,activeAppointments=GovernanceService.Current(db).Count(x=>x.PersonId==p.Id&&s.Ids.Contains(x.OrgId)&&x.TenantId==s.Workspace.TenantId),memberships=db.Memberships.Where(m=>m.PersonId==p.Id&&m.TenantId==s.Workspace.TenantId&&s.Ids.Contains(m.ClubId)).OrderBy(m=>m.JoinedAt).Select(m=>new{m.Id,m.Number,m.ClubId,m.Status,club=m.Club.Name}).Take(8).ToList(),offices=GovernanceService.Current(db).Where(x=>x.PersonId==p.Id&&s.Ids.Contains(x.OrgId)&&x.TenantId==s.Workspace.TenantId).Select(x=>new{x.Id,x.OrgId,title=db.OfficerPositions.Where(o=>o.Id==x.PositionId).Select(o=>o.Title).First(),organization=db.Orgs.Where(o=>o.Id==x.OrgId).Select(o=>o.Name).First()}).Take(10).ToList()}).ToListAsync();
        return Results.Ok(new{total,page,size=20,items,capabilities=new{contacts,staff},definition="One row per central person. Memberships and appointments are independent affiliations. Contacts require explicit field permissions; private contacts are not searched without those rights."});
    }
}
